SourceCode.Declaration:
/// <summary>
/// Collection class for logic components. Components are the content of a logic block. Components can be reused across multiple Logic blocks.
/// </summary>
class TFMLogicComponentCollection
{
    Map components;

}

Method.Source:
/// <summary>
/// Constructor
/// </summary>
protected void new()
{
    components = new Map(Types::Integer, Types::Class);
}

/// <summary>
/// Public constructor
/// </summary>
/// <returns>An initialized TFMLogicComponentCollection object.</returns>
public static TFMLogicComponentCollection Construct()
{
    return new TFMLogicComponentCollection();
}

public TFMReferenceDataConfiguration getHeaders()
{
    TFMReferenceDataConfiguration   refCon = new TFMReferenceDataConfiguration();
    TFMReferenceDataConfiguration   componentRefCon;
    TFMLogicComponent               component;
    MapEnumerator                   compEnum = components.getEnumerator();
    while (compEnum.moveNext())
    {
        component = compEnum.currentValue();
        componentRefCon = component.headerFieldsNeeded();
        if (componentRefCon == null)
        {
            continue;
        }
        refCon.mergeCollectors(componentRefCon);
    }
    return refCon;
}

public TFMRegistrationCollectors getCollectors()
{
    TFMRegistrationCollectors   collectors = TFMRegistrationCollectors::Construct();
    TFMLogicComponent           component;
    MApEnumerator               compEnum = components.getEnumerator();
    while (compEnum.moveNext())
    {
        component = compEnum.currentValue();

        collectors.mergeCollectors(component.registrationCollectors());
    }

    return collectors;
}

public TFMLogicComponent getComponent(ClassName _componentName)
{
    MapEnumerator mEnum = components.getEnumerator();
    TFMLogicComponent component;

    while (mEnum.moveNext())
    {
        component = mEnum.currentValue();

        if (classId2Name(classIdGet(component)) == _componentName)
        {
            return component;
        }
    }

    return null;
}

