public TFMRequestElement modifyRequest(TFMRequestElement _request)
{
    TFMLogicComponent           component;
    MapEnumerator               compEnum = components.getEnumerator();
    TFMRequestElement           request     = _request;
    while (compEnum.moveNext())
    {
        component = compEnum.currentValue();

        request = component.componentRequest(request);
    }
    return request;        
}

public void setRequests(TFMRequestElement _request)
{
    TFMLogicComponent           component;
    MapEnumerator               compEnum = components.getEnumerator();

    while (compEnum.moveNext())
    {
        component = compEnum.currentValue();

        component.setRequest(_request);
    }        
}

public Common provideDataIfPossible(Common _table)
{

    MapEnumerator               compEnum = components.getEnumerator();
    TFMLogicComponent           component;
    while (compEnum.moveNext())
    {
        component = compEnum.currentValue();

        component.provideDataIfPossible(_table);
    }
    return _table;
}
